const body = $json.body ?? $json;

if (!body.fileName || !body.contentType || !body.imageBase64) {
  throw new Error('Faltan fileName, contentType o imageBase64');
}

return [
  {
    json: {
      fileName: body.fileName,
      contentType: body.contentType
    },
    binary: {
      diagramImage: {
        data: Buffer.from(body.imageBase64, 'base64').toString('base64'),
        mimeType: body.contentType,
        fileName: body.fileName
      }
    }
  }
];

const raw =
  $json?.content?.parts?.[0]?.text ??
  $json?.text ??
  '';

if (!raw) {
  throw new Error('Gemini no devolvió contenido');
}

let cleaned = raw.trim();

cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error('La respuesta de Gemini no contiene JSON válido');
}

return [
  {
    json: parsed
  }
];

const input = $json;

if (input.success !== true) {
  return [
    {
      json: {
        success: false,
        warnings: Array.isArray(input.warnings) ? input.warnings : [],
        confidence: Number(input.confidence ?? 0)
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      diagram: {
        classes: Array.isArray(input.classes) ? input.classes : [],
        relations: Array.isArray(input.relations) ? input.relations : [],
        associationClasses: Array.isArray(input.associationClasses)
          ? input.associationClasses
          : []
      },
      warnings: Array.isArray(input.warnings) ? input.warnings : [],
      confidence: Number(input.confidence ?? 0),
      summary: input.summary ?? ''
    }
  }
];;
